SELECT Id, DisplayName, ModelIdentifier, IsEnabled AS en, IsDefault AS def, json_extract(CapabilityQualificationsJson,'$[0].UnetName') AS unet, json_extract(CapabilityQualificationsJson,'$[0].TextEncoderName') AS te, json_extract(CapabilityQualificationsJson,'$[0].VaeName') AS vae, json_extract(CapabilityQualificationsJson,'$[0].Steps') AS steps, json_extract(CapabilityQualificationsJson,'$[0].Cfg') AS cfg, json_extract(CapabilityQualificationsJson,'$[0].SamplerName') AS sampler, json_extract(CapabilityQualificationsJson,'$[0].Scheduler') AS sched FROM RegisteredModels WHERE SceneImageModelFamily=5 ORDER BY DisplayName;
